func opsCodeDiv(a, b uint32) uint32 {
	switch {
	case b == 0:
		return 0xffffffff
	case a == 0x80000000 && b == 0xffffffff:
		return 0x80000000
	}
	return uint32(int32(a) / int32(b))
}

func opsCodeDivu(a, b uint32) uint32 {
	if b == 0 {
		return 0xffffffff
	}
	return a / b
}

func opsCodeRem(a, b uint32) uint32 {
	switch {
	case b == 0:
		return a
	case a == 0x80000000 && b == 0xffffffff:
		return 0
	}
	return uint32(int32(a) % int32(b))
}

func opsCodeRemu(a, b uint32) uint32 {
	if b == 0 {
		return a
	}
	return a % b
}
